sed -i 's/export function ensureProductSections(product: Product): UiSection\[\] {/export function ensureProductSections(product: Product): UiSection[] {\n  const globals = localDb.global_groups || [];\n  const injectedGlobals: UiSection[] = (product.global_group_ids || [])\n    .map(gid => globals.find(g => g.id === gid))\n    .filter(Boolean)\n    .map((g, i) => ({\n      id: "global_" + g!.id,\n      type: g!.type,\n      title: g!.title,\n      enabled: true,\n      order: 1000 + i,\n      items: g!.items,\n      chips: g!.chips,\n      extras: g!.extras,\n      options: g!.options,\n      min_selection: g!.min_selection,\n      max_selection: g!.max_selection\n    } as UiSection));/' frontend/src/api/api.impl.ts
